/**
 * 케이슨 마을's distant mountains (B6, 2026-11-16: "먼 산의 모습도 실제와 비슷하도록 해") — the pure part.
 *
 * Several ridge rings round the valley, receding into haze like a real Korean valley view (art/village/refs/mountains/):
 * near ridges dark green with the forest's crowns and some granite, far ridges paler and bluer, the valleys between
 * them filled with haze. Generated by docs/designs/mountains/tools/build_mountains.py into two small files:
 *  - `mountains.v1.bin`: the ridge grid (per layer, per azimuth column and row: the radius and height of a vertex);
 *    the mesh (positions, UVs, a per-vertex "valley" weight) is built here, one draw call for every layer;
 *  - `mountains.v1.webp`: the colour atlas, one strip per layer (lit albedo, no haze).
 *
 * The aerial perspective is applied at run time, so it follows the time of day: the land colour (× the time of day's
 * land tint) fades with distance into the sky the dome shows at the horizon in that direction (the dome's own texture
 * and tint), more in the valleys. The material is display-referred like the dome (not tone-mapped; on the rich tier the
 * final pass's tone curve is undone, as the dome's is), so the farthest ridges melt into the sky at every hour.
 *
 * The old far range of village.glb (the flat blue-grey cut-out ridges) is cut out of the loaded clone beyond
 * `BACKDROP_CUT_RADIUS` (the backdrop's triangles wholly outside it and the forest cards standing outside it); the
 * village's near hills, the waterfall's ridge and the lake's basin stay. The village rebuild (W6) drops them for good
 * (docs/designs/mountains/README.md).
 */
import {
  BufferAttribute,
  BufferGeometry,
  Color,
  DoubleSide,
  Float32BufferAttribute,
  Matrix3,
  Matrix4,
  MeshBasicMaterial,
  Uint16BufferAttribute,
  Uint32BufferAttribute,
  Vector3,
  Vector4,
  type InstancedMesh,
  type Mesh,
  type Object3D,
  type Texture,
} from "three";
import { versionedUrl } from "./modelUrl";
import { ACES_IN_INV, ACES_OUT_INV, INVERSE_TONE_GLSL, type SkyMapping } from "./villageWater";
import type { ToneCurve } from "../game/quality";
import type { DayNightState, Rgb } from "./dayNightBlend";

export const MOUNTAINS_GRID_URL = versionedUrl("/models/village/mountains.v1.bin");
export const MOUNTAINS_TEXTURE_URL = versionedUrl("/models/village/mountains.v1.webp");

/** The old backdrop is cut beyond this radius (m from the plaza): the new rings' feet start at 215 m, under it. */
export const BACKDROP_CUT_RADIUS = 240;
/** The village's backdrop mesh and its forest cards (village.glb). */
const BACKDROP_MESH = "village_backdrop";
const FAR_FOREST = /^inst__far_/;

/** Look values (tuned against the reference photos, docs/designs/mountains/). */
export const MOUNTAIN_LOOK = {
  /**
   * Haze: 1 - exp(-((d - start) / distance)^power), d the distance from the camera (m): about 0.12 on the nearest
   * ridge (400 m), 0.3, 0.5 and 0.68 on the next ones (photos: the near ridges keep their dark green).
   */
  hazeStart: 150,
  hazeDistance: 1010,
  hazePower: 1.47,
  /** The extra haze in the valleys (the foot of each ridge): × (1 - t)^1.5. */
  valley: 0.45,
  /** The haze never quite hides the farthest ridge by day. */
  hazeMax: 0.86,
  /** The sky colour the haze takes: the dome's texture this far above the horizon (radians). */
  skyElevation: 0.03,
} as const;

// ───────────────────────────────────────── the grid file ─────────────────────────────────────────

export interface MountainLayer {
  segs: number;
  rows: number;
  /** The atlas v of the foot (t = 0) and the crest (t = 1), GL convention (0 = bottom of the image). */
  vFoot: number;
  vCrest: number;
  /** 0 nearest .. 1 farthest. */
  depth: number;
  /** Row parameters t (0 foot .. 1 crest), `rows` of them. */
  t: Float32Array;
  /** Radius and height (m) per vertex, row-major (row, seg). */
  radius: Float32Array;
  height: Float32Array;
}

const H_STEP = 0.05;
const H_OFFSET = -100;

/** Read `mountains.v1.bin` (see build_mountains.py for the layout). */
export function parseMountains(buffer: ArrayBuffer): MountainLayer[] {
  const view = new DataView(buffer);
  const magic = String.fromCharCode(view.getUint8(0), view.getUint8(1), view.getUint8(2), view.getUint8(3));
  if (magic !== "MTN1") throw new Error(`mountains: bad file (${magic})`);
  const count = view.getUint32(4, true);
  let o = 8;
  const heads: Array<Omit<MountainLayer, "radius" | "height">> = [];
  for (let i = 0; i < count; i++) {
    const segs = view.getUint32(o, true);
    const rows = view.getUint32(o + 4, true);
    const vFoot = view.getFloat32(o + 8, true);
    const vCrest = view.getFloat32(o + 12, true);
    const depth = view.getFloat32(o + 16, true);
    o += 20;
    const t = new Float32Array(rows);
    for (let r = 0; r < rows; r++, o += 4) t[r] = view.getFloat32(o, true);
    heads.push({ segs, rows, vFoot, vCrest, depth, t });
  }
  return heads.map((h) => {
    const n = h.segs * h.rows;
    const radius = new Float32Array(n);
    const height = new Float32Array(n);
    for (let k = 0; k < n; k++, o += 2) radius[k] = view.getUint16(o, true) * H_STEP;
    for (let k = 0; k < n; k++, o += 2) height[k] = H_OFFSET + view.getUint16(o, true) * H_STEP;
    return { ...h, radius, height };
  });
}

/**
 * One geometry for every layer: positions on the rings (azimuth clockwise from north, north = -z), the atlas UVs
 * (u = azimuth; the seam column is doubled so u runs 0..1 without a wrap), and `valley` = (1 - t) for the shader's
 * valley haze. Faces wind toward the centre (front faces seen from the village).
 */
export function buildMountainGeometry(layers: readonly MountainLayer[]): BufferGeometry {
  let verts = 0;
  let tris = 0;
  for (const L of layers) {
    verts += (L.segs + 1) * L.rows;
    tris += L.segs * (L.rows - 1) * 2;
  }
  const pos = new Float32Array(verts * 3);
  const uv = new Float32Array(verts * 2);
  const valley = new Float32Array(verts);
  const index = verts > 65535 ? new Uint32Array(tris * 3) : new Uint16Array(tris * 3);
  let v = 0;
  let k = 0;
  for (const L of layers) {
    const base = v;
    const cols = L.segs + 1;
    for (let r = 0; r < L.rows; r++) {
      const t = L.t[r]!;
      for (let c = 0; c < cols; c++, v++) {
        const s = c % L.segs;
        const az = (c / L.segs) * Math.PI * 2;
        const rad = L.radius[r * L.segs + s]!;
        pos[v * 3] = rad * Math.sin(az);
        pos[v * 3 + 1] = L.height[r * L.segs + s]!;
        pos[v * 3 + 2] = -rad * Math.cos(az);
        uv[v * 2] = c / L.segs;
        uv[v * 2 + 1] = L.vFoot + (L.vCrest - L.vFoot) * t;
        valley[v] = 1 - t;
      }
    }
    for (let r = 0; r < L.rows - 1; r++) {
      for (let c = 0; c < L.segs; c++) {
        const a = base + r * cols + c;
        const b = a + 1;
        const d = a + cols;
        const e = d + 1;
        // seen from the centre the azimuth grows to the right and the rows upward: (a, b, d) and (b, e, d) face inward
        index[k++] = a;
        index[k++] = b;
        index[k++] = d;
        index[k++] = b;
        index[k++] = e;
        index[k++] = d;
      }
    }
  }
  const g = new BufferGeometry();
  g.setAttribute("position", new Float32BufferAttribute(pos, 3));
  g.setAttribute("uv", new Float32BufferAttribute(uv, 2));
  g.setAttribute("valley", new Float32BufferAttribute(valley, 1));
  g.setIndex(index instanceof Uint32Array ? new Uint32BufferAttribute(index, 1) : new Uint16BufferAttribute(index, 1));
  g.computeBoundingSphere();
  return g;
}

// ───────────────────────────────────────── the material ─────────────────────────────────────────

export interface MountainUniforms {
  uSky: { value: Texture | null };
  uSkyMap: { value: Vector4 };
  uSkyTint: { value: Color };
  uHaze: { value: Vector4 };
  uHazePow: { value: number };
  uAcesInInv: { value: Matrix3 };
  uAcesOutInv: { value: Matrix3 };
  uExposure: { value: number };
}

const VERTEX_PARS = /* glsl */ `
attribute float valley;
varying float vValley;
varying vec3 vMtnWorld;
`;
const VERTEX_MAIN = /* glsl */ `
vValley = valley;
vMtnWorld = ( modelMatrix * vec4( transformed, 1.0 ) ).xyz;
`;
const FRAGMENT_PARS = /* glsl */ `
uniform sampler2D uSky;
uniform vec4 uSkyMap;
uniform vec3 uSkyTint;
uniform vec4 uHaze; // start, distance, valley, max
uniform float uHazePow;
varying float vValley;
varying vec3 vMtnWorld;
`;
// After the map: the land (map × the land tint in diffuse) fades into the dome's horizon sky in this direction.
const FRAGMENT_HAZE = /* glsl */ `
{
  vec3 toP = vMtnWorld - cameraPosition;
  float d = length( toP );
  vec3 dir = toP / max( d, 1e-3 );
  float az = atan( dir.x, dir.z );
  vec2 skyUv = vec2( fract( uSkyMap.x * az / PI2 + uSkyMap.y ), clamp( uSkyMap.z * ${MOUNTAIN_LOOK.skyElevation.toFixed(3)} + uSkyMap.w, 0.0, 1.0 ) );
  vec3 sky = textureLod( uSky, skyUv, 4.0 ).rgb * uSkyTint;
  float h = 1.0 - exp( -pow( max( d - uHaze.x, 0.0 ) / uHaze.y, uHazePow ) );
  float v = pow( clamp( vValley, 0.0, 1.0 ), 1.5 ) * uHaze.z;
  h = min( uHaze.w, h + v * ( 1.0 - h ) );
  diffuseColor.rgb = mix( diffuseColor.rgb, sky, h );
}
`;

/**
 * The mountains' material: unlit, its atlas × `color` (the land tint, set per frame), hazed toward the dome's sky.
 * Display-referred like the dome (`toneMapped` false; on the rich tier the final pass's curve is undone in the shader).
 */
export function createMountainMaterial(
  atlas: Texture,
  sky: { map: Texture | null; mapping: SkyMapping },
  tier: "high" | "low",
  curve: ToneCurve,
): MeshBasicMaterial {
  // double-sided: a far ravine wall may turn its back on the eye (always behind the near one; never a hole to the sky)
  const m = new MeshBasicMaterial({ map: atlas, fog: false, toneMapped: false, side: DoubleSide });
  m.name = "M_mountains";
  const s = sky.mapping;
  const uniforms: MountainUniforms = {
    uSky: { value: sky.map },
    uSkyMap: { value: new Vector4(s.uSign, s.uOffset, s.vScale, s.vOffset) },
    uSkyTint: { value: new Color(1, 1, 1) },
    uHaze: { value: new Vector4(MOUNTAIN_LOOK.hazeStart, MOUNTAIN_LOOK.hazeDistance, MOUNTAIN_LOOK.valley, MOUNTAIN_LOOK.hazeMax) },
    uHazePow: { value: MOUNTAIN_LOOK.hazePower },
    uAcesInInv: { value: new Matrix3().copy(ACES_IN_INV) },
    uAcesOutInv: { value: new Matrix3().copy(ACES_OUT_INV) },
    uExposure: { value: 1 },
  };
  m.userData.mountains = uniforms;
  const inverse = tier === "high";
  m.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace("#include <common>", `#include <common>\n${VERTEX_PARS}`)
      .replace("#include <fog_vertex>", `#include <fog_vertex>\n${VERTEX_MAIN}`);
    let frag = shader.fragmentShader
      .replace("#include <common>", `#include <common>\n${FRAGMENT_PARS}`)
      .replace("#include <map_fragment>", `#include <map_fragment>\n${FRAGMENT_HAZE}`);
    if (inverse) {
      frag = frag
        .replace("void main() {", `${curve === "neutral" ? "#define VILLAGE_INVERSE_NEUTRAL\n" : ""}${INVERSE_TONE_GLSL}\nvoid main() {`)
        .replace("#include <tonemapping_fragment>", "gl_FragColor.rgb = villageInverseTone( gl_FragColor.rgb );\n#include <tonemapping_fragment>");
    }
    shader.fragmentShader = frag;
  };
  m.customProgramCacheKey = () => `village-mountains-${inverse ? curve : "plain"}`;
  return m;
}

/**
 * The land's tint for a time of day (linear ×): white by day, the warm golden-hour cast, and at night the moonlit
 * dark a little below the dome's night tint (so the ridges stand dark against the night sky).
 */
export function mountainLandTint(s: DayNightState, into: Rgb = [1, 1, 1]): Rgb {
  const n = s.night;
  const g = s.golden * (1 - n);
  for (let i = 0; i < 3; i++) {
    const day = 1 + (GOLDEN_LAND[i]! - 1) * g;
    into[i] = day + (NIGHT_LAND[i]! - day) * n;
  }
  return into;
}

/** The land's warm cast at full golden hour, and its moonlit dark at night (linear ×, display-referred). */
export const GOLDEN_LAND: Rgb = [1.08, 0.84, 0.64];
export const NIGHT_LAND: Rgb = [0.03, 0.045, 0.1];

/** Per frame: the time of day into the mountains' uniforms (number writes only). */
export function applyMountains(material: MeshBasicMaterial, s: DayNightState, skyTint: Color | null, exposure: number): void {
  const u = material.userData.mountains as MountainUniforms;
  const tint = mountainLandTint(s, scratch);
  material.color.setRGB(tint[0], tint[1], tint[2]);
  if (skyTint) u.uSkyTint.value.copy(skyTint);
  else u.uSkyTint.value.setRGB(s.domeTint[0], s.domeTint[1], s.domeTint[2]);
  u.uExposure.value = exposure;
}
const scratch: Rgb = [1, 1, 1];

// ───────────────────────────────────────── cutting the old far range ─────────────────────────────────────────

const tmp = new Vector3();
const tmpM = new Matrix4();

export interface BackdropCut {
  trianglesRemoved: number;
  instancesRemoved: number;
  /** Put the clone back as it was (the original index, the instance count). */
  restore(): void;
}

/**
 * Cut the old far range out of a CLONE of the village model: the backdrop's triangles wholly beyond `radius` (from the
 * world origin, in x/z) and the far forest's instances standing beyond it. The geometry belongs to the loader's cache:
 * the trimmed mesh gets a copy sharing its attributes with a new index; `restore` gives the original back.
 */
export function cutFarBackdrop(root: Object3D, radius = BACKDROP_CUT_RADIUS): BackdropCut {
  const r2 = radius * radius;
  const undo: Array<() => void> = [];
  let trianglesRemoved = 0;
  let instancesRemoved = 0;
  root.updateMatrixWorld(true);
  root.traverse((o) => {
    if ((o as Mesh).isMesh && o.name === BACKDROP_MESH && !(o as InstancedMesh).isInstancedMesh) {
      const mesh = o as Mesh;
      const geo = mesh.geometry;
      const posAttr = geo.getAttribute("position") as BufferAttribute | undefined;
      if (!posAttr) return;
      const idx = geo.index;
      const triCount = idx ? idx.count / 3 : posAttr.count / 3;
      const out: number[] = [];
      const far = new Uint8Array(posAttr.count);
      for (let i = 0; i < posAttr.count; i++) {
        tmp.fromBufferAttribute(posAttr, i).applyMatrix4(mesh.matrixWorld);
        far[i] = tmp.x * tmp.x + tmp.z * tmp.z > r2 ? 1 : 0;
      }
      for (let t = 0; t < triCount; t++) {
        const a = idx ? idx.getX(t * 3) : t * 3;
        const b = idx ? idx.getX(t * 3 + 1) : t * 3 + 1;
        const c = idx ? idx.getX(t * 3 + 2) : t * 3 + 2;
        if (far[a] && far[b] && far[c]) trianglesRemoved++;
        else out.push(a, b, c);
      }
      if (out.length / 3 === triCount) return;
      const copy = new BufferGeometry();
      for (const name of Object.keys(geo.attributes)) copy.setAttribute(name, geo.getAttribute(name));
      copy.setIndex(posAttr.count > 65535 ? new Uint32BufferAttribute(out, 1) : new Uint16BufferAttribute(out, 1));
      copy.boundingSphere = geo.boundingSphere;
      copy.boundingBox = geo.boundingBox;
      const original = geo;
      mesh.geometry = copy;
      undo.push(() => {
        mesh.geometry = original;
        copy.dispose();
      });
      return;
    }
    if ((o as InstancedMesh).isInstancedMesh && FAR_FOREST.test(nameChain(o))) {
      const inst = o as InstancedMesh;
      const count = inst.count;
      const arr = inst.instanceMatrix.array as Float32Array;
      const saved = arr.slice(0, count * 16);
      let kept = 0;
      for (let i = 0; i < count; i++) {
        tmpM.fromArray(saved, i * 16).premultiply(inst.matrixWorld);
        const x = tmpM.elements[12]!;
        const z = tmpM.elements[14]!;
        if (x * x + z * z > r2) continue;
        if (kept !== i) arr.set(saved.subarray(i * 16, i * 16 + 16), kept * 16);
        kept++;
      }
      if (kept === count) return;
      instancesRemoved += count - kept;
      inst.count = kept;
      inst.instanceMatrix.needsUpdate = true;
      inst.boundingSphere = null;
      undo.push(() => {
        arr.set(saved, 0);
        inst.count = count;
        inst.instanceMatrix.needsUpdate = true;
        inst.boundingSphere = null;
      });
    }
  });
  return {
    trianglesRemoved,
    instancesRemoved,
    restore() {
      for (const u of undo.reverse()) u();
      undo.length = 0;
    },
  };
}

/** An object's name, or its parent's (glTF instancing puts the node's name on a parent group or on the mesh). */
function nameChain(o: Object3D): string {
  return FAR_FOREST.test(o.name) ? o.name : (o.parent?.name ?? "");
}
